fn sgn(v: i32) -> i32 {
    if v > 0 { return 1; }
    if v < 0 { return -1; }
    0
}

fn iabs(v: i32) -> i32 {
    if v < 0 { -v } else { v }
}

fn frame(t: i32) {
    let w: i32 = host::display::width();
    let h: i32 = host::display::height();
    let nx: i32 = 60;
    let ny: i32 = h - 60;
    let fx: i32 = w - 60;
    let fy: i32 = 70;
    if host::display::state_get(0) == 0 {
        host::display::state_set(0, 1);
        host::display::state_set(2, 55);
        let mut a: i32 = 0;
        while a < 2 {
            host::display::state_set(8 + a * 3, nx);
            host::display::state_set(9 + a * 3, ny);
            host::display::state_set(10 + a * 3, 0);
            a = a + 1;
        }
        let mut p: i32 = 0;
        while p < 24 {
            host::display::state_set(16 + p * 2, nx);
            host::display::state_set(17 + p * 2, ny);
            p = p + 1;
        }
    }
    let mut seed: i32 = host::display::state_get(2);
    let mut trips: i32 = host::display::state_get(3);
    let mut a: i32 = 0;
    while a < 2 {
        let b: i32 = 8 + a * 3;
        let mut x: i32 = host::display::state_get(b);
        let mut y: i32 = host::display::state_get(b + 1);
        let mut mode: i32 = host::display::state_get(b + 2);
        let tx: i32 = if mode == 0 { fx } else { nx };
        let ty: i32 = if mode == 0 { fy } else { ny };
        seed = seed * 1103515245 + 12345;
        let jx: i32 = ((seed >> 16) & 4095) % 3 - 1;
        let jy: i32 = ((seed >> 8) & 4095) % 3 - 1;
        x = x + sgn(tx - x) * 2 + jx;
        y = y + sgn(ty - y) * 2 + jy;
        if iabs(tx - x) <= 8 && iabs(ty - y) <= 8 {
            if mode == 0 { trips = trips + 1; }
            mode = 1 - mode;
        }
        host::display::state_set(b, x);
        host::display::state_set(b + 1, y);
        host::display::state_set(b + 2, mode);
        if t % 4 == a * 2 {
            let head: i32 = host::display::state_get(4);
            host::display::state_set(16 + head * 2, x);
            host::display::state_set(17 + head * 2, y);
            host::display::state_set(4, (head + 1) % 24);
        }
        a = a + 1;
    }
    host::display::state_set(2, seed);
    host::display::state_set(3, trips);
    host::display::clear(0x100e0a);
    let mut p: i32 = 0;
    while p < 24 {
        let px: i32 = host::display::state_get(16 + p * 2);
        let py: i32 = host::display::state_get(17 + p * 2);
        host::display::fill_rect(px - 2, py - 2, 4, 4, 0x706428);
        p = p + 1;
    }
    host::display::fill_rect(nx - 12, ny - 12, 24, 24, 0x805030);
    host::display::fill_rect(fx - 10, fy - 10, 20, 20, 0x30a040);
    a = 0;
    while a < 2 {
        let x: i32 = host::display::state_get(8 + a * 3);
        let y: i32 = host::display::state_get(9 + a * 3);
        host::display::fill_rect(x - 4, y - 4, 8, 8, 0xe0e0e0);
        a = a + 1;
    }
    host::display::draw_string(8, 8, "TRIPS", 0x808080, 1);
    host::display::draw_number(60, 8, trips, 0xffffff, 1);
    host::display::present();
}
